+	/* FDB refresh is raised from the switch offload path (AF) after
+	 * switchdev FDB updates.  PF-local ports are refreshed here on
+	 * pf->netdev.  CGX VF port refreshes for VM-bridged offload are
+	 * forwarded to the guest VF via the PF-VF mailbox when hdr.pcifunc
+	 * carries VF func bits (see rvu_sw_l2_fdb_refresh_send()).
+	 */
+	item.addr = req->mac;
+	item.info.dev = pf->netdev;
+	if (req->flags & OTX2_FDB_DEL)
+		call_switchdev_notifiers(SWITCHDEV_FDB_DEL_TO_BRIDGE,
+					 item.info.dev, &item.info, NULL);
+	else
+		call_switchdev_notifiers(SWITCHDEV_FDB_ADD_TO_BRIDGE,
+					 item.info.dev, &item.info, NULL);
+
+	return 0;
+}
 #endif
