+static int otx2_mqprio_validate_tc_rate(struct net_device *netdev, u64 rate,
+					u32 qcount, int tc, const char *name)
+{
+	if (!rate || qcount <= 1 || rate >= qcount)
+		return 0;
+
+	netdev_err(netdev,
+		   "mqprio: %s rate %llu for tc %d too small for %u queues\n",
+		   name, rate, tc, qcount);
+	return -EINVAL;
+}
